{
  "metric": "daily yellow taxi trip count",
  "target_window": "2024-12-21 (Saturday)",
  "baseline_window": "2024-12-07, 2024-12-14, 2024-12-28 (other Saturdays in December 2024)",
  "hypotheses": [
    {
      "id": "H0",
      "kind": "metric",
      "statement": "Trips on 2024-12-21 were lower than the average of the other three Saturdays in December 2024.",
      "support_if": "2024-12-21 trips < mean(trips on 2024-12-07, 2024-12-14, 2024-12-28) by a meaningful margin (e.g., >5-10%).",
      "refute_if": "2024-12-21 trips >= mean of other Saturdays, or difference is negligible (<5%)."
    },
    {
      "id": "H1",
      "kind": "weather",
      "statement": "Snowfall on 2024-12-21 suppressed trip demand relative to other Saturdays with no snow.",
      "support_if": "snow_mm > 0 on 2024-12-21 and snow_mm = 0 on all other Dec 2024 Saturdays; trips on 2024-12-21 are lower.",
      "refute_if": "snow_mm = 0 on 2024-12-21, or other Saturdays also had snow but trips were not similarly reduced."
    },
    {
      "id": "H2",
      "kind": "holiday",
      "statement": "A holiday on or near 2024-12-21 (e.g., Christmas week) altered travel patterns vs. other Saturdays.",
      "support_if": "A federal/state holiday falls on 2024-12-21 or adjacent weekdays, and trip pattern differs from non-holiday Saturdays.",
      "refute_if": "No holiday on 2024-12-21 or adjacent days; or holidays present on other baseline Saturdays too."
    },
    {
      "id": "H3",
      "kind": "day_of_week",
      "statement": "The pre-Christmas Saturday (21st) has intrinsically different demand than early/mid-December Saturdays, regardless of weather.",
      "support_if": "Historical pattern (if available) shows last Saturday before Christmas is lower; but no prior years in data. Instead, check if 2024-12-28 (post-Christmas) is also low, suggesting seasonal effect.",
      "refute_if": "2024-12-28 trips are similar to 12-07 and 12-14, making 12-21 an outlier."
    },
    {
      "id": "H4",
      "kind": "fare_mix",
      "statement": "The mix of trip distances/fares shifted on 2024-12-21 (e.g., fewer short trips), indicating behavioral change beyond volume.",
      "support_if": "avg_trip_distance or avg_total_amount on 2024-12-21 differs significantly from other Saturdays, suggesting different trip purposes.",
      "refute_if": "avg_trip_distance and avg_total_amount on 2024-12-21 are consistent with other Saturdays; only volume dropped."
    },
    {
      "id": "H5",
      "kind": "data_quality",
      "statement": "The low trip count on 2024-12-21 is due to missing or incomplete data ingestion for that day.",
      "support_if": "Trip count is implausibly low (e.g., near zero or <50% of baseline) AND avg_total_amount/avg_trip_distance are NULL or extreme outliers.",
      "refute_if": "Trip count is reduced but avg_total_amount and avg_trip_distance are reasonable and consistent with other days."
    }
  ],
  "queries": [
    {
      "hypothesis_id": "H0",
      "purpose": "Get daily trip counts for all Saturdays in December 2024 to quantify the target vs baseline difference.",
      "tables": ["whybot.yellow_daily", "TPCDS_DB.date_dim"]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Get snowfall (snow_mm) for each Saturday in December 2024 to test if 2024-12-21 had snow and others did not.",
      "tables": ["whybot.nyc_weather_daily", "TPCDS_DB.date_dim"]
    },
    {
      "hypothesis_id": "H2",
      "purpose": "Check for US holidays on or around each Saturday in December 2024 (including 2024-12-21) to assess holiday impact.",
      "tables": ["whybot.us_holidays", "TPCDS_DB.date_dim"]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Compare trip counts on 2024-12-21 vs 2024-12-28 (post-Christmas Saturday) to isolate pre-Christmas seasonal effect.",
      "tables": ["whybot.yellow_daily", "TPCDS_DB.date_dim"]
    },
    {
      "hypothesis_id": "H4",
      "purpose": "Compare avg_trip_distance and avg_total_amount on 2024-12-21 vs other Dec 2024 Saturdays to detect fare/distance mix shift.",
      "tables": ["whybot.yellow_daily", "TPCDS_DB.date_dim"]
    },
    {
      "hypothesis_id": "H5",
      "purpose": "Check data completeness on 2024-12-21: verify trips > 0 and avg_total_amount, avg_trip_distance are non-null and plausible.",
      "tables": ["whybot.yellow_daily"]
    }
  ],
  "rationale": "The plan quantifies the trip count difference (H0) and tests five competing explanations: weather (H1 - snowfall), holiday (H2), seasonal/weekday pattern (H3 - pre-Christmas vs post-Christmas Saturday), behavioral mix shift (H4 - fare/distance), and data quality (H5). All queries use only catalog tables, stay within 2024-12-01 to 2024-12-31, and are aggregated at daily level. The baseline uses the other three Saturdays in December 2024 for like-for-like weekday comparison."
}

{
  "sql": "SELECT y.trip_date, y.trips, w.snow_mm, d.d_day_name FROM whybot.yellow_daily y JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date LEFT JOIN whybot.nyc_weather_daily w ON w.obs_date = y.trip_date WHERE y.trip_date BETWEEN DATE '2024-11-01' AND DATE '2024-12-31' AND d_dow = 7 ORDER BY y.trip_date",
  "tables_used": [
    "whybot.yellow_daily",
    "TPCDS_DB.date_dim",
    "whybot.nyc_weather_daily"
  ],
  "note": "Saturdays in Dec 2024 only; snow_mm may be NULL for days without weather data"
}

{
  "sql": "SELECT y.trip_date, w.snow_mm, d.d_day_name FROM whybot.yellow_daily y JOIN whybot.nyc_weather_daily w ON w.obs_date = y.trip_date JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE d.d_dow = 7 AND y.trip_date BETWEEN DATE '2024-12-01' AND DATE '2024-12-31' ORDER BY y.trip_date",
  "tables_used": [
    "whybot.yellow_daily",
    "whybot.nyc_weather_daily",
    "TPCDS_DB.date_dim"
  ],
  "note": "Filter d_dow=7 targets Saturdays; date range covers all Saturdays in December 2024."
}

{
  "sql": "SELECT y.trip_date, y.trips, w.snow_mm, h.holiday_name, d.d_day_name FROM whybot.yellow_daily y JOIN whybot.nyc_weather_daily w ON w.obs_date = y.trip_date LEFT JOIN whybot.us_holidays h ON h.holiday_date = y.trip_date JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE y.trip_date BETWEEN DATE '2024-12-01' AND DATE '2024-12-31' AND d_dow = 6 ORDER BY y.trip_date",
  "tables_used": [
    "whybot.yellow_daily",
    "whybot.nyc_weather_daily",
    "whybot.us_holidays",
    "TPCDS_DB.date_dim"
  ],
  "note": "Filters to Saturdays (d_dow=6) in December 2024 and left-joins holidays so non-holiday Saturdays still appear with NULL holiday_name."
}

{
  "sql": "SELECT y.trip_date, y.trips, y.avg_total_amount, y.avg_trip_distance, d.d_day_name FROM whybot.yellow_daily y JOIN whybot.nyc_weather_daily w ON w.obs_date = y.trip_date LEFT JOIN whybot.us_holidays h ON h.holiday_date = y.trip_date JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE y.trip_date BETWEEN DATE '2024-12-01' AND DATE '2024-12-31' AND d.d_day_name = 'Saturday' ORDER BY y.trip_date",
  "tables_used": ["whybot.yellow_daily", "whybot.nyc_weather_daily", "whybot.us_holidays", "TPCDS_DB.date_dim"],
  "note": "Filters to December 2024 Saturdays; LEFT JOIN on holidays ensures one row per date even if no holiday"
}

